nt-size: 28rpx;\n  color: #666666;\n}\n\n.divider {\n  height: 2rpx;\n  background-color: #eeeeee;\n  margin: 20rpx 0;\n}\n\n.status-time {\n  display: flex;\n  justify-content: space-between;\n  font-size: 28rpx;\n  color: #333333;\n}\n\n.status-text {\n  color: #ff9900;\n  font-weight: bold;\n}\n\n.tag-title {\n  font-size: 28rpx;\n  margin-bottom: 10rpx;\n}\n\n.tags {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12rpx;\n}\n\n.tag-item {\n  background-color: #f1f1f1;\n  padding: 10rpx 20rpx;\n  border-radius: 20rpx;\n  font-size: 26rpx;\n  color: #444;\n}\n\n.member-header {\n  margin-bottom: 20rpx;\n}\n\n.member-title {\n  font-size: 28rpx;\n  font-weight: bold;\n}\n\n.member-count {\n  font-size: 26rpx;\n  color: #999999;\n  margin-top: 10rpx;\n}\n\n.member {\n  display: flex;\n  align-items: center;\n  padding: 20rpx 0;\n  border-bottom: 1px solid #f0f0f0;\n}\n\n.cover-img {\n  width: 100%;\n  height: 300rpx;\n  border-radius: 16rpx;\n  object-fit: cover;\n  background-color: #f0f0f0;\n  display: block;\n}\n\n.member-avatar {\n  width: 100rpx;\n  height: 100rpx;\n  border-radius: 50%;\n  object-fit: cover;\n  background-color: #eee;\n  margin-right: 20rpx;\n}\n\n\n.member-info {\n  flex: 1;\n}\n\n.member-name {\n  font-size: 30rpx;\n  font-weight: bold;\n  margin-bottom: 8rpx;\n}\n\n.member-role {\n  font-size: 26rpx;\n  color: #888;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.kick-btn {\n  margin-left: 20rpx;\n  padding: 10rpx 20rpx;\n  background-color: #ff4d4f;\n  color: white;\n  font-size: 24rpx;\n  border-radius: 8rpx;\n  border: none;\n  line-height: 1;\n}\n\n.kick-btn::after {\n  display: none;\n}\n\n.application-item {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin: 10rpx 0;\n  padding: 16rpx;\n  border: 1px solid #f0f0f0;\n  border-radius: 12rpx;\n}\n\n.apply-btn-wrapper {\n\tdisplay: flex;\n\tjustify-content: center;\n\tmargin-top: 20rpx;\n}\n\n.apply-btn {\n\tbackground